WITH unpivoted AS (SELECT * FROM (SELECT id, device_code, temp_c, humidity, pressure FROM device_readings) src UNPIVOT (metric_value FOR measure IN (temp_c AS TEMP_C_VAL, humidity AS HUMIDITY, pressure))) SELECT measure, device_code, COUNT(*) AS cnt, MIN(metric_value) AS min_metric_value, COUNT(*) AS event_count, COUNT(*) AS event_count_2, SUM(CASE WHEN device_code = 'DV-04' THEN metric_value ELSE 0 END) AS dv_04_metric_value, ROUND(AVG(metric_value), 2) AS avg_metric_value FROM unpivoted GROUP BY 1, 2 HAVING MIN(metric_value) >= 0 ORDER BY measure DESC;
